<?php
namespace ProjectPress\Includes\Core;
use ProjectPress\Includes\Core\WP\Database;
if(!defined('ABSPATH')){exit;}
final class Schema{
 public static function register_tables():void{
  self::register('settings',self::settings_schema());self::register('analytics',self::analytics_schema());self::register('logs',self::logs_schema());self::register('projects',self::projects_schema());self::register('project_term_relationships',self::project_term_relationships_schema());self::register('teams',self::teams_schema());self::register('team_members',self::team_members_schema());self::register('project_teams',self::project_teams_schema());self::register('project_fields',self::project_fields_schema());self::register('project_field_values',self::project_field_values_schema());self::register('workspaces',self::workspaces_schema());self::register('project_relationships',self::project_relationships_schema());self::register('activity',self::activity_schema());self::register('tasks',self::tasks_schema());
 }
 private static function register(string $name,string $columns):void{Database::register_core_table($name,static fn(string $table_name,string $charset):string=>"CREATE TABLE {$table_name} (\n{$columns}\n) {$charset};");}
 private static function settings_schema():string{return "id bigint(20) unsigned NOT NULL AUTO_INCREMENT,\nsetting_group varchar(120) NOT NULL,\nsetting_value longtext DEFAULT NULL,\nautoload varchar(20) NOT NULL DEFAULT 'yes',\nupdated_at datetime DEFAULT NULL,\nPRIMARY KEY  (id),\nUNIQUE KEY setting_group (setting_group)";}
 private static function analytics_schema():string{return "id bigint(20) unsigned NOT NULL AUTO_INCREMENT,\nevent_key varchar(128) NOT NULL,\nevent_value longtext DEFAULT NULL,\nuser_id bigint(20) unsigned DEFAULT NULL,\nevent_source varchar(64) DEFAULT NULL,\ncreated_at datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,\nupdated_at datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,\nPRIMARY KEY  (id),\nKEY event_key (event_key),\nKEY created_at (created_at),\nKEY user_id (user_id)";}
 private static function logs_schema():string{return "id bigint(20) unsigned NOT NULL AUTO_INCREMENT,\nlog_level varchar(32) NOT NULL,\nmessage longtext NOT NULL,\ncontext longtext DEFAULT NULL,\nsource varchar(64) DEFAULT NULL,\ncreated_at datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,\nupdated_at datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,\nPRIMARY KEY  (id),\nKEY log_level (log_level),\nKEY source (source),\nKEY created_at (created_at)";}
 private static function projects_schema():string{return "id bigint(20) unsigned NOT NULL AUTO_INCREMENT,\nproject_name varchar(191) NOT NULL,\nproject_slug varchar(191) NOT NULL,\nproject_key varchar(32) NOT NULL,\nproject_description longtext DEFAULT NULL,\nparent_id bigint(20) unsigned DEFAULT NULL,\nowner_id bigint(20) unsigned DEFAULT NULL,\nstatus varchar(32) NOT NULL DEFAULT 'planning',\npriority varchar(32) NOT NULL DEFAULT 'normal',\nvisibility varchar(32) NOT NULL DEFAULT 'private',\nstart_date datetime DEFAULT NULL,\ntarget_end_date datetime DEFAULT NULL,\nactual_end_date datetime DEFAULT NULL,\ncreated_by bigint(20) unsigned DEFAULT NULL,\ncreated_at datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,\nupdated_by bigint(20) unsigned DEFAULT NULL,\nupdated_at datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,\nPRIMARY KEY  (id),\nUNIQUE KEY project_key (project_key),\nUNIQUE KEY project_slug (project_slug),\nKEY parent_id (parent_id),\nKEY owner_id (owner_id),\nKEY status (status),\nKEY priority (priority),\nKEY visibility (visibility),\nKEY updated_at (updated_at)";}
 private static function project_term_relationships_schema():string{return "project_id bigint(20) unsigned NOT NULL,\nterm_id bigint(20) unsigned NOT NULL,\ntaxonomy varchar(32) NOT NULL,\nassigned_by bigint(20) unsigned DEFAULT NULL,\nassigned_at datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,\nPRIMARY KEY  (project_id,term_id,taxonomy),\nKEY term_taxonomy (term_id,taxonomy),\nKEY taxonomy (taxonomy)";}
 private static function teams_schema():string{return "id bigint(20) unsigned NOT NULL AUTO_INCREMENT,\nteam_name varchar(191) NOT NULL,\nteam_slug varchar(191) NOT NULL,\nteam_description longtext DEFAULT NULL,\nowner_id bigint(20) unsigned DEFAULT NULL,\nstatus varchar(32) NOT NULL DEFAULT 'active',\ncreated_by bigint(20) unsigned DEFAULT NULL,\ncreated_at datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,\nupdated_by bigint(20) unsigned DEFAULT NULL,\nupdated_at datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,\nPRIMARY KEY  (id),\nUNIQUE KEY team_slug (team_slug),\nKEY owner_id (owner_id),\nKEY status (status)";}
 private static function team_members_schema():string{return "id bigint(20) unsigned NOT NULL AUTO_INCREMENT,\nteam_id bigint(20) unsigned NOT NULL,\nuser_id bigint(20) unsigned NOT NULL,\nmember_role varchar(32) NOT NULL DEFAULT 'member',\nmember_status varchar(32) NOT NULL DEFAULT 'active',\nadded_by bigint(20) unsigned DEFAULT NULL,\njoined_at datetime DEFAULT NULL,\ncreated_at datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,\nupdated_at datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,\nPRIMARY KEY  (id),\nUNIQUE KEY team_user (team_id,user_id),\nKEY user_id (user_id),\nKEY member_status (member_status)";}
 private static function project_teams_schema():string{return "id bigint(20) unsigned NOT NULL AUTO_INCREMENT,\nproject_id bigint(20) unsigned NOT NULL,\nteam_id bigint(20) unsigned NOT NULL,\nteam_role varchar(32) NOT NULL DEFAULT 'contributor',\nassigned_by bigint(20) unsigned DEFAULT NULL,\nassigned_at datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,\nPRIMARY KEY  (id),\nUNIQUE KEY project_team (project_id,team_id),\nKEY team_id (team_id)";}
 private static function project_fields_schema():string{return "id bigint(20) unsigned NOT NULL AUTO_INCREMENT,\nfield_key varchar(120) NOT NULL,\nfield_name varchar(191) NOT NULL,\nfield_description longtext DEFAULT NULL,\nfield_type varchar(32) NOT NULL,\nconfiguration longtext DEFAULT NULL,\nis_required tinyint(1) NOT NULL DEFAULT 0,\nis_enabled tinyint(1) NOT NULL DEFAULT 1,\nsort_order int(11) NOT NULL DEFAULT 0,\ncreated_by bigint(20) unsigned DEFAULT NULL,\ncreated_at datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,\nupdated_by bigint(20) unsigned DEFAULT NULL,\nupdated_at datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,\nPRIMARY KEY  (id),\nUNIQUE KEY field_key (field_key),\nKEY field_type (field_type),\nKEY enabled_order (is_enabled,sort_order)";}
 private static function project_field_values_schema():string{return "id bigint(20) unsigned NOT NULL AUTO_INCREMENT,\nproject_id bigint(20) unsigned NOT NULL,\nfield_id bigint(20) unsigned NOT NULL,\nvalue_text varchar(191) DEFAULT NULL,\nvalue_longtext longtext DEFAULT NULL,\nvalue_number decimal(20,6) DEFAULT NULL,\nvalue_date datetime DEFAULT NULL,\ncreated_at datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,\nupdated_by bigint(20) unsigned DEFAULT NULL,\nupdated_at datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,\nPRIMARY KEY  (id),\nUNIQUE KEY project_field (project_id,field_id),\nKEY field_id (field_id),\nKEY value_date (value_date)";}
 private static function workspaces_schema():string{return "id bigint(20) unsigned NOT NULL AUTO_INCREMENT,\nworkspace_name varchar(120) NOT NULL,\nworkspace_slug varchar(120) NOT NULL,\nworkspace_description longtext DEFAULT NULL,\ncreated_by bigint(20) unsigned DEFAULT NULL,\ncreated_at datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,\nupdated_at datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,\nPRIMARY KEY  (id),\nUNIQUE KEY workspace_slug (workspace_slug)";}
 private static function project_relationships_schema():string{return "id bigint(20) unsigned NOT NULL AUTO_INCREMENT,\nsource_project_id bigint(20) unsigned NOT NULL,\ntarget_project_id bigint(20) unsigned NOT NULL,\nrelationship varchar(32) NOT NULL,\ncreated_by bigint(20) unsigned DEFAULT NULL,\ncreated_at datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,\nPRIMARY KEY  (id),\nUNIQUE KEY project_relationship (source_project_id,target_project_id,relationship),\nKEY target_project_id (target_project_id),\nKEY relationship (relationship)";}
 private static function activity_schema():string{return "id bigint(20) unsigned NOT NULL AUTO_INCREMENT,\nproject_id bigint(20) unsigned NOT NULL,\nobject_type varchar(50) NOT NULL,\nobject_id bigint(20) unsigned DEFAULT NULL,\naction varchar(80) NOT NULL,\nactor_id bigint(20) unsigned DEFAULT NULL,\nactivity_summary text DEFAULT NULL,\nactivity_data longtext DEFAULT NULL,\ncreated_at datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,\nPRIMARY KEY  (id),\nKEY project_created (project_id,created_at),\nKEY object_lookup (object_type,object_id),\nKEY actor_id (actor_id),\nKEY action (action)";}
 private static function tasks_schema():string{return "id bigint(20) unsigned NOT NULL AUTO_INCREMENT,\nproject_id bigint(20) unsigned NOT NULL,\ntask_title varchar(191) NOT NULL,\ntask_description longtext DEFAULT NULL,\nstatus varchar(32) NOT NULL DEFAULT 'todo',\npriority varchar(32) NOT NULL DEFAULT 'normal',\nassignee_id bigint(20) unsigned DEFAULT NULL,\ndue_date datetime DEFAULT NULL,\nsort_order int(11) NOT NULL DEFAULT 0,\ncreated_by bigint(20) unsigned DEFAULT NULL,\ncreated_at datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,\nupdated_by bigint(20) unsigned DEFAULT NULL,\nupdated_at datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,\nPRIMARY KEY  (id),\nKEY project_status (project_id,status),\nKEY project_order (project_id,sort_order),\nKEY assignee_id (assignee_id),\nKEY due_date (due_date)";}
}
